[1879514701]={[1]="Pouch of An Shêru Salt";[2]="A pouch of salt ground out of the dry soil of An Shêru. The Temámir of Jiret-menêsh prize this for their dishes, and have been without it since retreating within the mountain. Faction: Temámir of Jiret-menêsh (250 points) Use this item to immediately gain reputation in this faction.";[3]=89;[4]=4;[5]=0;[6]=false;[7]=false;};
