[1879514703]={[1]="Bounty of Unsullied Seeds";[2]="A bounty of unsullied seeds recovered from the blighted land of Adagím. The Kintai at Sul Madásh believe they can use these seeds to restore the forest of Nisigím. Faction: Kintai of Sul Madásh (500 points) Use this item to immediately gain reputation in this faction.";[3]=89;[4]=2;[5]=0;[6]=false;[7]=false;};
